--scrolling keybind
hl.bind("SUPER + comma", hl.dsp.layout("move -col"))
hl.bind("SUPER + period", hl.dsp.layout("move +col"))
hl.bind("SUPER + SHIFT + comma", hl.dsp.layout("swapcol l"))
hl.bind("SUPER + SHIFT + period", hl.dsp.layout("swapcol r"))
hl.bind("SUPER + ALT + comma", hl.dsp.layout("consume prev"))
hl.bind("SUPER + ALT + period", hl.dsp.layout("consume next"))
hl.bind("SUPER + ALT + SHIFT + comma", hl.dsp.layout("expel prev"))
hl.bind("SUPER + ALT + SHIFT + period", hl.dsp.layout("expel next"))

--apps
hl.bind("SUPER + T", hl.dsp.exec_cmd("[float;size 900 700;center] alacritty"))
hl.bind("SUPER + R", hl.dsp.exec_cmd("rofi -show drun"))
hl.bind("SUPER + W", hl.dsp.exec_cmd("rofi -show windoscroll_mw"))
hl.bind("CTRL + SHIFT + T", hl.dsp.exec_cmd("alacritty"))
hl.bind("CTRL + SHIFT + W", hl.dsp.exec_cmd("~/.scripts/webapps.rofi.py launch"))
hl.bind("CTRL + SHIFT + E", hl.dsp.exec_cmd("alacritty -e bash -ic yazi"))
hl.bind("CTRL + SHIFT + G", hl.dsp.exec_cmd("[float;size 900 700;center] qutebrowser"))
hl.bind("CTRL + SHIFT + S", hl.dsp.exec_cmd("[float;size 600 400;move cursor_x-10 cursor_y-30] alacritty -e python -q -i ~/.scripts/pyshell.py"))
hl.bind("CTRL + SHIFT + A", hl.dsp.exec_cmd("[float;size 500 200;move cursor_x-10 cursor_y-30] alacritty -e qalc -c -e -i"))
hl.bind("CTRL + SHIFT + N", hl.dsp.exec_cmd("alacritty -e nvim"))
hl.bind("CTRL + SHIFT + B", hl.dsp.exec_cmd("emacsclient -c -a 'emacs'"))

-- Window Management
hl.bind("SUPER + Q", hl.dsp.window.close())
hl.bind("SUPER + M", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind("SUPER + SHIFT + M", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind("SUPER + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind("SUPER + G", hl.dsp.group.toggle())

-- Numbered Workspaces
hl.bind("SUPER + 1", hl.dsp.focus({ workspace = 1 }))
