-- Special Controls 
hl.bind("SUPER + TAB", hl.dsp.exec_cmd("dms ipc call lock lock"))
hl.bind("CTRL + SHIFT + XF86AudioMute", hl.dsp.exec_cmd("[float;size 900 700;center] pavucontrol"))
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("dms ipc call audio increment 1"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("dms ipc call audio decrement 1"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("dms ipc call audio mute"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("dms ipc call audio micmute"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("dms ipc call mpris playPause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("dms ipc call mpris playPause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("dms ipc call mpris previous"), { locked = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("dms ipc call mpris next"), { locked = true })
hl.bind("CTRL + XF86AudioRaiseVolume", hl.dsp.exec_cmd("dms ipc call mpris increment 3"), { locked = true, repeating = true })
hl.bind("CTRL + XF86AudioLowerVolume", hl.dsp.exec_cmd("dms ipc call mpris decrement 3"), { locked = true, repeating = true })

hl.bind("CTRL + SHIFT + F5", hl.dsp.exec_cmd("[float;size 900 700;center] pavucontrol"))
hl.bind("CTRL + F7", hl.dsp.exec_cmd("dms ipc call audio increment 1"), { locked = true, repeating = true })
hl.bind("CTRL + F6", hl.dsp.exec_cmd("dms ipc call audio decrement 1"), { locked = true, repeating = true })
hl.bind("CTRL + F5", hl.dsp.exec_cmd("dms ipc call audio mute"), { locked = true })
hl.bind("CTRL + F8", hl.dsp.exec_cmd("dms ipc call audio micmute"), { locked = true })
hl.bind("CTRL + F10", hl.dsp.exec_cmd("dms ipc call mpris previous"), { locked = true })
hl.bind("CTRL + F11", hl.dsp.exec_cmd("dms ipc call mpris playPause"), { locked = true })
hl.bind("CTRL + F12", hl.dsp.exec_cmd("dms ipc call mpris next"), { locked = true })

hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("dms ipc call brightness increment 5 \"\""), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("dms ipc call brightness decrement 5 \"\""), { locked = true, repeating = true })
hl.bind("CTRL + F4", hl.dsp.exec_cmd("dms ipc call brightness increment 5 \"\""), { locked = true, repeating = true })
hl.bind("CTRL + f3", hl.dsp.exec_cmd("dms ipc call brightness decrement 5 \"\""), { locked = true, repeating = true })

-- Mouse Wheel Navigation
hl.bind("SUPER + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind("SUPER + mouse_up", hl.dsp.focus({ workspace = "e-1" }))
hl.bind("SUPER + CTRL + mouse_down", hl.dsp.window.move({ workspace = "e+1" }))
hl.bind("SUPER + CTRL + mouse_up", hl.dsp.window.move({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { description = "Move window" })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { description = "Resize window" })

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind("SUPER + code:20", hl.dsp.window.resize({ x = -100, y = 0, relative = true }), { description = "Expand window left" })
hl.bind("SUPER + code:21", hl.dsp.window.resize({ x = 100, y = 0, relative = true }), { description = "Shrink window left" })

-- Screenshots
hl.bind("Print", hl.dsp.exec_cmd("dms screenshot"))
hl.bind("CTRL + Print", hl.dsp.exec_cmd("dms screenshot full"))
hl.bind("ALT + Print", hl.dsp.exec_cmd("dms screenshot window"))

